package conectate.com.presentation.experience

import android.provider.MediaStore
import android.webkit.WebView
import androidx.compose.material3.MaterialTheme
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.test.espresso.Espresso.onView
import androidx.test.espresso.UiController
import androidx.test.espresso.ViewAction
import androidx.test.espresso.matcher.ViewMatchers.isAssignableFrom
import androidx.test.platform.app.InstrumentationRegistry
import conectate.com.presentation.surveys.SurveyWorkbench
import org.hamcrest.Matcher
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import java.util.UUID
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit

/** Real packaged WebView -> native bridge -> MediaStore -> byte comparison. Synthetic responses only. */
class SurveyExportUiTest {
    @get:Rule val compose = createComposeRule()
    private lateinit var web: WebView
    private val exports = JSONArray("""[{"name":"Descarga de prueba.xlsx","mime":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","data":"","format":"xlsx"},{"name":"Descarga de prueba.csv","mime":"text/csv;charset=utf-8","data":"77u/IlJlc3B1ZXN0YSIsIkVudmlhZGEgVVRDIiwiQWN0dWFsaXphZGEgVVRDIiwiQ29tZW50YXJpbyIsIkNvbWVudGFyaW8g4oCUIGVzdGFkbyINCiIyMjIyMjIyMi0yMjIyLTQyMjItODIyMi0yMjIyMjIyMjIyMjIiLCIyMDI2LTEwLTA4VDEwOjAxOjAwLjAwMFoiLCIyMDI2LTEwLTA4VDEwOjAxOjAwLjAwMFoiLCJSZXNwdWVzdGEgc2ludMOpdGljYSIsIlJlc3BvbmRpZGEi","format":"csv"},{"name":"Descarga de prueba-informe.docx","mime":"application/vnd.openxmlformats-officedocument.wordprocessingml.document","data":"","format":"docx"},{"name":"Descarga de prueba-informe.pdf","mime":"application/pdf","data":"","format":"pdf"}]""")
    private val prefix = "Novvin_export_audit_${UUID.randomUUID()}"
    private var serverFailure = false
    private var corruptDownload = false
    private var exportCalls = 0
    private fun transport(raw: String, receive: (JSONObject) -> Unit) {
        val input = JSONObject(raw); val path = input.getString("path").removePrefix("/v1/surveys")
        val reply = JSONObject().put("id", input.getString("id"))
        if (path.endsWith("/export") && serverFailure) { receive(reply.put("error", "Exportación no disponible.")); return }
        val value = when {
            path == "/me" -> JSONObject().put("id", "qa-owner")
            path == "/forms" -> JSONObject().put("forms", JSONArray())
            path == "/campaigns" -> JSONObject().put("campaigns", JSONArray().put(JSONObject()
                .put("id", "qa-export").put("schema", JSONObject("""{"title":"Descarga de prueba","questions":[]}"""))
                .put("status", "open").put("revision", 1).put("response_count", 1).put("visibility", "public").put("post_exists", true)))
            path.startsWith("/campaigns/qa-export/results?") -> JSONObject().put("total", 1).put("page", 0).put("pages", 1)
                .put("responses", JSONArray()).put("questions", JSONArray()).put("timeline", JSONArray()).put("caveat", "Prueba sintética")
            path == "/campaigns/qa-export/export" -> {
                exportCalls++
                val format = input.getJSONObject("body").getString("format")
                val file = (0 until exports.length()).map { exports.getJSONObject(it) }.first { it.getString("format") == format }
                JSONObject(file.toString()).put("name", "$prefix.$format").apply { if (corruptDownload) put("data", "malformed!") }
            }
            else -> error("Unexpected export fixture route")
        }
        receive(reply.put("value", value))
    }
    private fun js(value: String): String {
        val latch = CountDownLatch(1);var output = ""
        InstrumentationRegistry.getInstrumentation().runOnMainSync { web.evaluateJavascript(value) { output=it;latch.countDown() } }
        assertTrue(latch.await(10,TimeUnit.SECONDS));return output
    }
    private fun awaitJs(value: String) {
        val until=System.nanoTime()+TimeUnit.SECONDS.toNanos(20)
        while(System.nanoTime()<until) { if(js("Boolean($value)")=="true")return;Thread.sleep(50) }
        fail("Export UI did not settle: $value")
    }
    private fun click(action: String) {
        js("document.querySelector('[data-action=\"$action\"]').click()")
        awaitJs("document.getElementById('app').getAttribute('aria-busy') === 'false'")
    }
    private fun start() {
        compose.setContent { MaterialTheme { SurveyWorkbench(onBack={},request=::transport) } }
        onView(isAssignableFrom(WebView::class.java)).perform(object:ViewAction {
            override fun getConstraints():Matcher<android.view.View> = isAssignableFrom(WebView::class.java)
            override fun getDescription()="Get owned export WebView"
            override fun perform(controller:UiController,view:android.view.View){web=view as WebView}
        })
        awaitJs("document.querySelector('[data-action=manage]')");click("manage");click("exports")
    }
    private fun files(): List<Pair<String,android.net.Uri>> {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val collection=MediaStore.Downloads.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)
        val rows=mutableListOf<Pair<String,android.net.Uri>>()
        context.contentResolver.query(collection,arrayOf(MediaStore.MediaColumns._ID,MediaStore.MediaColumns.DISPLAY_NAME),
            MediaStore.MediaColumns.DISPLAY_NAME+" LIKE ?",arrayOf("$prefix.%"),null)?.use { cursor ->
            while(cursor.moveToNext()) rows += cursor.getString(1) to android.content.ContentUris.withAppendedId(collection,cursor.getLong(0))
        }
        return rows
    }
    private fun cleanup() {
        val resolver=InstrumentationRegistry.getInstrumentation().targetContext.contentResolver
        files().forEach { (_,uri) -> resolver.delete(uri,null,null) }
    }
    @Test fun allFourFormatsDownloadFromWebViewAndHaveExactBytesAndMime() {
        try { start();val resolver=InstrumentationRegistry.getInstrumentation().targetContext.contentResolver
            for(i in 0 until exports.length()) {
                val file=exports.getJSONObject(i);val format=file.getString("format")
                js("document.getElementById('export-format').value='$format'");click("download-export")
                assertEquals("true",js("document.getElementById('notice').textContent.includes('Archivo guardado: $prefix.$format')"))
                val uri=files().single { it.first=="$prefix.$format" }.second
                val expectedMime=file.getString("mime").substringBefore(';')
                val actualMime=resolver.getType(uri)
                // Android MediaProvider canonicalizes .csv to text/comma-separated-values.
                if(format=="csv") assertTrue(actualMime in setOf("text/csv","text/comma-separated-values"))
                else assertEquals(expectedMime,actualMime)
                val expected=android.util.Base64.decode(file.getString("data"),android.util.Base64.DEFAULT)
                assertArrayEquals(expected,resolver.openInputStream(uri)!!.use { it.readBytes() })
            }
            assertEquals(4,exportCalls);assertEquals(4,files().size)
        } finally { cleanup() }
    }
    @Test fun failedExportDoesNotCreateFileAndRetryWorks() {
        try { start();serverFailure=true;click("download-export");assertTrue(files().isEmpty())
            assertEquals("true",js("document.getElementById('notice').textContent.includes('Exportación no disponible')"))
            serverFailure=false;click("download-export");assertEquals(1,files().size)
        } finally { cleanup() }
    }
    @Test fun corruptPayloadIsRejectedBeforeCreatingDownload() {
        try { start();corruptDownload=true;click("download-export");assertTrue(files().isEmpty())
            assertEquals("true",js("!document.getElementById('notice').textContent.includes('Archivo guardado')"))
            assertEquals("true",js("!document.querySelector('[data-action=download-export]').disabled"))
        } finally { cleanup() }
    }
}
